from collections import deque, Counter

def background(grid):
    """The most common color in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]

def flood_from_border(grid, color):
    """The set of cells of `color` reachable from the grid border (4-connectivity)."""
    H, W = len(grid), len(grid[0])
    q = deque((i, j) for i in range(H) for j in range(W)
              if grid[i][j] == color and (i in (0, H - 1) or j in (0, W - 1)))
    seen = set(q)
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            n = (i + di, j + dj)
            if 0 <= n[0] < H and 0 <= n[1] < W and grid[n[0]][n[1]] == color and n not in seen:
                seen.add(n)
                q.append(n)
    return seen

